<?phpnamespace App\Models;use Illuminate\Database\Eloquent\Factories\HasFactory;use Illuminate\Database\Eloquent\Model;use Illuminate\Support\Facades\DB;class HairModel extends Model{    use HasFactory;    public static function addHairColor($insert)    {        DB::table('hair')        ->insert($insert);        return DB::getPdo()        ->lastInsertId();    }    public static function getHairColor($lang,$hair_id)    {     $data=DB::table('hair');         if(empty($lang)){              $data ->select('*');         }else{              $data ->select('color_name_' . $lang . ' as color_name', 'hair_id');         }        return  $data=$data ->where('hair_id', $hair_id)      ->where('status', '!=', 'Deleted')      ->get()      ->first();    }    public static function getAllHairColor($lang)    {       $data=DB::table('hair');         if(empty($lang)){              $data ->select('*');         }else{              $data ->select('color_name_' . $lang . ' as color_name', 'hair_id');         }     return  $data=$data->where('status', '!=', 'Deleted')->get();    }    public static function updateHairColor($update, $hair_id)    {        return DB::table('hair')            ->where('hair_id', $hair_id)            ->update($update);    }     public static function deleteHairColor($hair_id){        return DB::table('hair')        ->where('hair_id',$hair_id)        ->update(['status'=>'Deleted']);     }    }